CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT UNIQUE, c1 TEXT DEFAULT 'd', c2 REAL, c3 REAL UNIQUE, c4 REAL COLLATE NOCASE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(640.877, NULL, 978, 3.141592653589793, NULL);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(3.141592653589793, 893, NULL, NULL, x'1ca7fc');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(NULL, 'naïve', 'psi', 3, -6.6);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER, c1 VARCHAR(10), c2 BLOB, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES('alpha', 'x_y', x'd38043d28f35', 5);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(NULL, -5, 'rho', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(195, 'naïve', 520.76, NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(4.5e-310, 'nu', 688.0692, 2);
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES('psi', 4, 257, 3);
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -2, 5), instr('it''s', 'epsilon'), replace('it''s', 'e', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '%a_', 'it''s' GLOB '*[a-m]*', char(81, 563), 'it''s' || 'epsilon', 'it''s' < 'epsilon', 'it''s' = 'epsilon' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 4, 2), instr('Ελλάδα', 'theta'), replace('Ελλάδα', 'e', ''), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE 'a%', 'Ελλάδα' GLOB '*', char(85, 211), 'Ελλάδα' || 'theta', 'Ελλάδα' < 'theta', 'Ελλάδα' = 'theta' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', 4, 4), instr('x_y', '0x1F'), replace('x_y', '', ''), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE '%', 'x_y' GLOB 'a*', char(74, 357), 'x_y' || '0x1F', 'x_y' < '0x1F', 'x_y' = '0x1F' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -3, 2), instr('it''s', 'pi'), replace('it''s', 'e', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '%a_', 'it''s' GLOB '*[a-m]*', char(70, 527), 'it''s' || 'pi', 'it''s' < 'pi', 'it''s' = 'pi' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 3, 0), instr('xi', 'nu'), replace('xi', 'e', 'XY'), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE 'A%', 'xi' GLOB '*', char(83, 839), 'xi' || 'nu', 'xi' < 'nu', 'xi' = 'nu' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', -3, 5), instr('upsilon', 'zeta'), replace('upsilon', 'a', 'XY'), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%', 'upsilon' GLOB '*', char(74, 760), 'upsilon' || 'zeta', 'upsilon' < 'zeta', 'upsilon' = 'zeta' COLLATE NOCASE;
SELECT a.id, b.id, a.c0, b.id FROM t0 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 30;
SELECT count(*) FROM t0 a JOIN t0 b USING(id) WHERE a.c3;
